import * as weave from 'weave';

// Initialize Weave
await weave.init('intro-example');

// Define the function to evaluate
const myModel = weave.op(
  async ({question}) => {
    // here's where you would add your LLM call and return the output
    return 'Paris';
  },
  {name: 'myModel'}
);

